/// Pinned SHA-256 (hex, lowercase) for a published release asset file name;
/// returns nullptr when the file is not a published asset. Qt-free on
/// purpose: usable from non-Qt targets. Qt callers use
/// ecvAssetIntegrity::PinnedDigest(fileName) which wraps this lookup.
inline const char* AssetDigestForFile(const char* fileName) {
    if (fileName == nullptr) return nullptr;
    for (const AssetDigestEntry& e : kAssetDigests) {
        if (std::strcmp(e.file, fileName) == 0) return e.sha256;
    }
    return nullptr;
}

